/**
 * Copies the Pyodide runtime out of node_modules and into public/pyodide.
 *
 * Pyodide is self-hosted rather than pulled from a CDN at runtime. Three
 * reasons, in order of how much they matter for this product:
 *
 *   1. Schools routinely block public CDNs. A CDN dependency could make every
 *      lesson fail on exactly the networks our students are sitting on.
 *   2. A third-party outage would take the whole course offline.
 *   3. Serving same-origin avoids cross-origin restrictions on worker loads.
 *
 * The copied files are build output, so they are gitignored and regenerated by
 * prebuild. Anything deploying this must run the build, not just serve the
 * repo as-is.
 */

import { createRequire } from "node:module";
import { copyFile, mkdir, stat } from "node:fs/promises";
import { dirname, join } from "node:path";

const require = createRequire(import.meta.url);

// Only the core runtime. The scientific packages in the full distribution are
// not used by this curriculum, and the standard library covers math/random.
const RUNTIME_FILES = [
  "pyodide.mjs",
  "pyodide.asm.mjs",
  "pyodide.asm.wasm",
  "python_stdlib.zip",
  "pyodide-lock.json",
];

async function main() {
  const entry = require.resolve("pyodide");
  const source = dirname(entry);
  const target = join(process.cwd(), "public", "pyodide");

  await mkdir(target, { recursive: true });

  let total = 0;
  for (const file of RUNTIME_FILES) {
    const from = join(source, file);
    const to = join(target, file);
    await copyFile(from, to);
    total += (await stat(to)).size;
  }

  const mb = (total / 1024 / 1024).toFixed(1);
  console.log(
    `pyodide: copied ${RUNTIME_FILES.length} runtime files (${mb} MB) to public/pyodide`,
  );
}

main().catch((error) => {
  console.error("pyodide: failed to stage runtime\n", error);
  process.exit(1);
});
